-- BUDDY: catálogo ampliado (decisión de Pablo, 18/11). Una sola migración, idéntica en staging y prod.
-- Criterio de etiquetas (guardarraíl 6; docs/catalogo-revision-2026-11-18.md):
--   joints        articulaciones que el ejercicio carga: con cualquiera limitada, el ejercicio se EXCLUYE.
--   joints_light  contribución leve (regla de Pablo, 18/11): si la ÚNICA coincidencia con las limitaciones
--                 está aquí, el ejercicio NO se excluye, pero la sesión muestra light_note y la técnica.
--   Ante la duda, la articulación va a joints. Nunca se quita una etiqueta existente (solo se añaden).
-- technique: 1–2 frases de cómo hacerlo bien. light_note: qué vigilar y parar si duele. No es consejo médico.
-- Regiones nuevas "brazo" y "core": solo se usan en huecos extra de la plantilla y como relleno (D68);
-- nunca en los 6 huecos principales. En equipo sin carga externa (suelo, barra de dominadas, paralelas,
-- banco de hiperextensiones), el peso es el lastre añadido y empieza en 0.

alter table public.exercises
  add column technique text,
  add column light_note text,
  add column joints_light text[] not null default '{}';

-- Zona "core" para la máquina de abdominales y la esterilla.
alter table public.equipment_types drop constraint equipment_types_zone_check;
alter table public.equipment_types add constraint equipment_types_zone_check
  check (zone in ('pierna', 'espalda', 'pecho_hombro', 'brazo', 'core', 'peso_libre', 'cardio'));

-- La máquina de gemelos del catálogo semilla es la de pie, con hombreras (la sentada es un tipo nuevo).
update public.equipment_types set name = 'Máquina de gemelos de pie' where id = 'maquina_gemelos';

on conflict (id) do nothing;

-- Ejercicios nuevos.
on conflict (id) do nothing;

-- Ejercicios existentes: técnica, contribución leve y las adiciones de etiquetas de la revisión del 18/11
-- (sentadilla_hack y sentadilla_multipower + espalda alta/hombro; gemelo_maquina + espalda baja y alta).
-- joints repite las etiquetas actuales más las añadidas: ninguna se quita.
update public.exercises as e set
  joints = v.joints::text[],
  joints_light = v.joints_light::text[],
  technique = v.technique,
  light_note = v.light_note
from (values
  ('press_pecho_maquina', '{hombro,codo}', '{muneca}', 'Ajusta el asiento para que las asas queden a la altura del pecho. Empuja sin despegar la espalda del respaldo y vuelve despacio.', 'Las muñecas aguantan algo de carga: mantenlas rectas, alineadas con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  ('press_banca_mancuernas', '{hombro,codo,muneca}', '{}', 'Omóplatos juntos y pies firmes en el suelo. Baja las mancuernas a los lados del pecho con los codos a unos 45 grados del cuerpo.', null),
  ('press_banca_barra', '{hombro,codo,muneca}', '{}', 'Agarre algo más ancho que los hombros y omóplatos juntos. Baja la barra controlada hasta el pecho y empuja sin rebotar.', null),
  ('press_pecho_polea', '{hombro,codo}', '{muneca}', 'Da un paso adelante con un pie y el tronco firme. Empuja las asas hacia delante y vuelve despacio sin que los codos pasen la espalda.', 'Las muñecas aguantan algo de carga: mantenlas rectas, alineadas con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  ('aperturas_contractora', '{hombro}', '{}', 'Codos un poco flexionados y fijos durante todo el recorrido. Junta las asas delante del pecho y abre sin pasar la línea de los hombros.', null),
  ('press_hombro_maquina', '{hombro,codo}', '{muneca,cuello_espalda_alta}', 'Espalda pegada al respaldo y asas a la altura de los hombros. Empuja hacia arriba sin bloquear los codos y baja despacio.', 'Hay zonas que trabajan poco aquí: carga ligera, recorrido cómodo y sin prisa. Si notas dolor, para y márcalo como molestia.'),
  ('press_militar_mancuernas', '{hombro,codo,muneca}', '{cuello_espalda_alta}', 'Sentado con la espalda apoyada. Sube las mancuernas sin arquear la zona lumbar y bájalas hasta la altura de las orejas.', 'Cuello y espalda alta trabajan algo: no encojas los hombros hacia las orejas. Si notas dolor, para y márcalo como molestia.'),
  ('press_hombro_multipower', '{hombro,codo,muneca}', '{cuello_espalda_alta}', 'Sentado en un banco con respaldo, la barra baja por delante de la cara. Empuja sin arquear la espalda y controla la bajada.', 'Cuello y espalda alta trabajan algo: no encojas los hombros hacia las orejas. Si notas dolor, para y márcalo como molestia.'),
  ('elevaciones_laterales_maq', '{hombro}', '{}', 'Apoya bien el pecho o la espalda en la máquina. Sube los brazos hasta la altura de los hombros, sin encogerlos, y baja despacio.', null),
  ('elevaciones_laterales_manc', '{hombro}', '{}', 'Codos un poco flexionados y tronco quieto. Sube hasta la altura de los hombros, sin impulso, y baja más despacio de lo que subes.', null),
  ('remo_sentado_polea', '{hombro,codo}', '{}', 'Pecho alto y tronco quieto. Lleva el agarre al abdomen juntando los omóplatos y vuelve estirando los brazos sin balancearte.', null),
  ('remo_maquina', '{hombro,codo}', '{}', 'Pecho apoyado en el respaldo. Tira con los codos hacia atrás, junta los omóplatos y vuelve sin soltar la tensión.', null),
  ('remo_mancuerna', '{hombro,codo,espalda_baja}', '{}', 'Apoya una mano y una rodilla en el banco con la espalda recta. Sube la mancuerna hacia la cadera sin girar el tronco.', null),
  ('pajaro_contractora', '{hombro}', '{}', 'Pecho contra el respaldo y brazos casi rectos. Abre hacia atrás hasta la línea de los hombros y vuelve despacio.', null),
  ('jalon_pecho', '{hombro,codo}', '{}', 'Muslos bien sujetos bajo el rodillo. Baja la barra a la parte alta del pecho con el pecho alto y sube despacio.', null),
  ('jalon_agarre_estrecho', '{hombro,codo}', '{}', 'Agarre estrecho y tronco un poco inclinado atrás. Lleva el agarre al pecho con los codos pegados y sube controlando.', null),
  ('jalon_polea_doble', '{hombro,codo}', '{}', 'Arrodillado o sentado frente a la polea. Tira de las asas hacia los hombros con los codos hacia abajo y sube despacio.', null),
  ('pullover_polea', '{hombro}', '{}', 'Brazos casi rectos y tronco algo inclinado. Lleva la barra o la cuerda hasta los muslos y vuelve sin pasar por encima de la cabeza.', null),
  ('prensa_piernas', '{rodilla,cadera}', '{espalda_baja}', 'Pies a la anchura de la cadera en el centro de la plataforma. Baja hasta donde la zona lumbar no se despegue del respaldo y empuja sin bloquear las rodillas.', 'La zona lumbar trabaja algo: mantén la espalda neutra y no arquees al final. Si notas dolor, para y márcalo como molestia.'),
  ('sentadilla_hack', '{rodilla,cadera,espalda_baja,cuello_espalda_alta}', '{hombro}', 'Espalda pegada al respaldo y pies algo adelantados. Baja controlando y sube empujando con todo el pie, sin bloquear las rodillas.', 'Tu hombro participa poco aquí: las hombreras apoyan sobre él. Si notas dolor, para y márcalo como molestia.'),
  ('sentadilla_multipower', '{rodilla,cadera,espalda_baja,hombro,cuello_espalda_alta}', '{}', 'Barra sobre la parte alta de la espalda y pies algo adelantados. Baja con el pecho alto hasta un recorrido cómodo y sube sin bloquear las rodillas.', null),
  ('sentadilla_goblet', '{rodilla,cadera}', '{espalda_baja,codo,muneca}', 'Sujeta la pesa pegada al pecho con los codos hacia abajo. Baja entre las piernas con el pecho alto y sube empujando con todo el pie.', 'Hay zonas que trabajan poco aquí: carga ligera, recorrido cómodo y sin prisa. Si notas dolor, para y márcalo como molestia.'),
  ('extension_cuadriceps', '{rodilla}', '{}', 'Ajusta el respaldo para que la rodilla quede alineada con el eje de la máquina. Sube sin impulso y baja despacio.', null),
  ('zancada_mancuernas', '{rodilla,cadera,tobillo}', '{espalda_baja,muneca}', 'Paso largo y tronco recto. Baja hasta que la rodilla de atrás casi toque el suelo y vuelve empujando con el talón de delante.', 'Hay zonas que trabajan poco aquí: carga ligera, recorrido cómodo y sin prisa. Si notas dolor, para y márcalo como molestia.'),
  ('gemelo_maquina', '{tobillo,espalda_baja,cuello_espalda_alta}', '{hombro}', 'Puntas de los pies en el borde y rodillas casi rectas. Sube todo lo que puedas, aguanta un segundo arriba y baja hasta notar el estiramiento.', 'Tu hombro participa poco aquí: las hombreras apoyan sobre él. Si notas dolor, para y márcalo como molestia.'),
  ('curl_femoral_tumbado', '{rodilla}', '{}', 'Rodillas justo por fuera del borde del banco y cadera pegada. Lleva los talones hacia los glúteos y baja despacio.', null),
  ('curl_femoral_sentado', '{rodilla}', '{}', 'Rodilla alineada con el eje de la máquina y muslos sujetos. Flexiona hasta el final y vuelve controlando.', null),
  ('peso_muerto_rumano_manc', '{espalda_baja,cadera}', '{muneca,cuello_espalda_alta}', 'Rodillas un poco flexionadas y espalda recta. Lleva la cadera atrás bajando las mancuernas pegadas a las piernas hasta notar el estiramiento.', 'Hay zonas que trabajan poco aquí: carga ligera, recorrido cómodo y sin prisa. Si notas dolor, para y márcalo como molestia.'),
  ('peso_muerto_rumano_barra', '{espalda_baja,cadera}', '{muneca,cuello_espalda_alta}', 'Barra pegada a las piernas y espalda recta. Lleva la cadera atrás hasta notar el estiramiento detrás del muslo y sube apretando los glúteos.', 'Hay zonas que trabajan poco aquí: carga ligera, recorrido cómodo y sin prisa. Si notas dolor, para y márcalo como molestia.'),
  ('hip_thrust_maquina', '{cadera}', '{espalda_baja}', 'Espalda alta apoyada y pies a la anchura de la cadera. Sube apretando los glúteos hasta alinear tronco y muslos, sin arquear la zona lumbar.', 'La zona lumbar trabaja algo: mantén la espalda neutra y no arquees al final. Si notas dolor, para y márcalo como molestia.'),
  ('hip_thrust_barra', '{cadera}', '{espalda_baja}', 'Espalda alta en el banco y barra con protector sobre la cadera. Sube hasta alinear tronco y muslos, con la barbilla recogida, sin arquear.', 'La zona lumbar trabaja algo: mantén la espalda neutra y no arquees al final. Si notas dolor, para y márcalo como molestia.'),
  ('abductores_maquina', '{cadera}', '{}', 'Espalda apoyada y movimiento lento. Abre las piernas sin impulso y vuelve sin dejar que las placas choquen.', null)
) as v(id, joints, joints_light, technique, light_note)
where e.id = v.id;

-- Una articulación es principal o leve, nunca las dos.
alter table public.exercises add constraint exercises_joints_light_disjoint check (not (joints && joints_light));
