insert into public.exercises (id, name, equipment_type_id, pattern, region, muscle_groups, joints, joints_light, calibration_load_kg, technique, light_note) values
  ('press_inclinado_mancuernas', 'Press inclinado con mancuernas', 'mancuernas', 'empuje_horizontal', 'empuje_superior_horizontal', '{pecho,hombros,triceps}', '{hombro,codo,muneca}', '{}', 6, 'Banco a unos 30 grados y omóplatos juntos. Baja las mancuernas a los lados de la parte alta del pecho y empuja sin chocarlas.', null),
  ('press_inclinado_barra', 'Press inclinado con barra', 'barra', 'empuje_horizontal', 'empuje_superior_horizontal', '{pecho,hombros,triceps}', '{hombro,codo,muneca}', '{}', 20, 'Banco inclinado y pies firmes. Baja la barra a la parte alta del pecho, controlada, y empuja sin rebotar.', null),
  ('press_inclinado_maquina', 'Press inclinado en máquina', 'press_inclinado_maquina', 'empuje_horizontal', 'empuje_superior_horizontal', '{pecho,hombros,triceps}', '{hombro,codo}', '{muneca}', 15, 'Asas a la altura de la parte alta del pecho. Empuja sin despegar la espalda y vuelve despacio.', 'Las muñecas aguantan algo de carga: mantenlas rectas, alineadas con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  ('press_banca_multipower', 'Press de banca en multipower', 'multipower', 'empuje_horizontal', 'empuje_superior_horizontal', '{pecho,triceps,hombros}', '{hombro,codo,muneca}', '{}', 10, 'Coloca el banco para que la barra baje a la mitad del pecho. Omóplatos juntos y baja controlando.', null),
  ('press_inclinado_multipower', 'Press inclinado en multipower', 'multipower', 'empuje_horizontal', 'empuje_superior_horizontal', '{pecho,hombros,triceps}', '{hombro,codo,muneca}', '{}', 10, 'Banco inclinado bajo la barra, que debe bajar a la parte alta del pecho. Empuja sin bloquear los codos.', null),
  ('aperturas_mancuernas', 'Aperturas con mancuernas', 'mancuernas', 'aperturas', 'empuje_superior_horizontal', '{pecho}', '{hombro,codo}', '{}', 4, 'Codos un poco flexionados y fijos. Abre hasta notar el estiramiento en el pecho, sin pasar la línea de los hombros, y cierra en arco.', null),
  ('cruce_poleas', 'Cruce de poleas', 'polea_doble', 'aperturas', 'empuje_superior_horizontal', '{pecho}', '{hombro,codo}', '{}', 5, 'Un paso adelante y tronco algo inclinado. Junta las asas delante del pecho en arco y vuelve despacio sin pasar la línea de los hombros.', null),
  ('fondos_paralelas', 'Fondos en paralelas', 'paralelas', 'fondos', 'empuje_superior_horizontal', '{pecho,triceps,hombros}', '{hombro,codo,muneca}', '{}', 0, 'El peso es el lastre extra: empieza sin lastre. Baja hasta que los codos formen un ángulo recto, sin hundir los hombros, y sube.', null),
  ('flexiones', 'Flexiones', 'esterilla', 'empuje_horizontal', 'empuje_superior_horizontal', '{pecho,triceps,hombros}', '{hombro,codo,muneca}', '{}', 0, 'Manos algo más anchas que los hombros y cuerpo en línea recta. Baja el pecho cerca del suelo y sube sin hundir la cadera. El peso es el lastre extra.', null),
  ('press_suelo_mancuernas', 'Press en el suelo con mancuernas', 'mancuernas', 'empuje_horizontal', 'empuje_superior_horizontal', '{pecho,triceps}', '{hombro,codo,muneca}', '{}', 6, 'Tumbado en el suelo con las rodillas dobladas. Baja hasta que los brazos toquen el suelo sin apoyarlos de golpe y empuja.', null),
  ('press_militar_barra', 'Press militar con barra de pie', 'barra', 'empuje_vertical', 'empuje_superior_vertical', '{hombros,triceps}', '{hombro,codo,muneca,espalda_baja}', '{cuello_espalda_alta}', 20, 'Glúteos y abdomen apretados para no arquear la espalda. Sube la barra por delante de la cara y termina con ella sobre la cabeza.', 'Cuello y espalda alta trabajan algo: no encojas los hombros hacia las orejas. Si notas dolor, para y márcalo como molestia.'),
  ('press_arnold', 'Press Arnold con mancuernas', 'mancuernas', 'empuje_vertical', 'empuje_superior_vertical', '{hombros,triceps}', '{hombro,codo,muneca}', '{}', 5, 'Sentado con la espalda apoyada. Empieza con las palmas hacia ti y gíralas hacia fuera mientras subes, sin arquear la espalda.', null),
  ('elevaciones_laterales_polea', 'Elevación lateral en polea', 'polea_doble', 'elevacion_lateral', 'empuje_superior_vertical', '{hombros}', '{hombro}', '{}', 2.5, 'Polea baja y de lado a la máquina. Sube el brazo hasta la altura del hombro con el codo algo flexionado y baja despacio.', null),
  ('elevaciones_frontales_manc', 'Elevaciones frontales con mancuernas', 'mancuernas', 'elevacion_frontal', 'empuje_superior_vertical', '{hombros}', '{hombro}', '{}', 4, 'Tronco quieto y codos casi rectos. Sube las mancuernas por delante hasta la altura de los hombros y baja sin balanceo.', null),
  ('flexiones_pica', 'Flexiones en pica', 'esterilla', 'empuje_vertical', 'empuje_superior_vertical', '{hombros,triceps}', '{hombro,codo,muneca}', '{}', 0, 'Cadera alta, en forma de V invertida. Baja la cabeza hacia el suelo entre las manos y empuja. El peso es el lastre extra.', null),
  ('press_hombro_kettlebell', 'Press de hombro con kettlebell', 'kettlebells', 'empuje_vertical', 'empuje_superior_vertical', '{hombros,triceps}', '{hombro,codo,muneca}', '{}', 8, 'La pesa descansa sobre el antebrazo con la muñeca recta. Empuja hacia arriba sin arquear la espalda y baja controlando.', null),
  ('remo_barra', 'Remo con barra', 'barra', 'traccion_horizontal', 'traccion_superior_horizontal', '{espalda,biceps}', '{hombro,codo,espalda_baja,muneca}', '{}', 20, 'Tronco inclinado unos 45 grados y espalda recta. Lleva la barra al abdomen juntando los omóplatos, sin dar tirones.', null),
  ('remo_pecho_apoyado_manc', 'Remo con mancuernas en banco inclinado', 'mancuernas', 'traccion_horizontal', 'traccion_superior_horizontal', '{espalda,biceps}', '{hombro,codo}', '{}', 8, 'Pecho apoyado en un banco inclinado. Sube las mancuernas hacia la cadera juntando los omóplatos y baja estirando los brazos.', null),
  ('remo_polea_unilateral', 'Remo a una mano en polea', 'polea_doble', 'traccion_horizontal', 'traccion_superior_horizontal', '{espalda,biceps}', '{hombro,codo,espalda_baja}', '{}', 5, 'Polea a media altura y tronco firme. Tira del asa hacia la cadera sin girar el cuerpo y vuelve despacio.', null),
  ('remo_multipower', 'Remo en multipower', 'multipower', 'traccion_horizontal', 'traccion_superior_horizontal', '{espalda,biceps}', '{hombro,codo,espalda_baja}', '{}', 10, 'Tronco inclinado y espalda recta, rodillas algo flexionadas. Lleva la barra al abdomen y bájala sin redondear la espalda.', null),
  ('face_pull', 'Face pull en polea', 'polea_doble', 'aperturas_inversas', 'traccion_superior_horizontal', '{hombros,espalda}', '{hombro,codo}', '{}', 10, 'Cuerda a la altura de la cara. Tira hacia la frente separando las manos y con los codos altos, y vuelve despacio.', null),
  ('pajaro_mancuernas_inclinado', 'Pájaro con mancuernas en banco inclinado', 'mancuernas', 'aperturas_inversas', 'traccion_superior_horizontal', '{hombros,espalda}', '{hombro}', '{}', 3, 'Pecho apoyado en el banco y brazos casi rectos. Abre hacia los lados hasta la línea de los hombros y baja despacio.', null),
  ('remo_polea_agarre_ancho', 'Remo en polea con agarre ancho', 'remo_polea', 'traccion_horizontal', 'traccion_superior_horizontal', '{espalda,hombros,biceps}', '{hombro,codo}', '{}', 20, 'Barra larga con agarre ancho y codos abiertos. Tira hacia la parte baja del pecho sin balancear el tronco.', null),
  ('remo_maquina_unilateral', 'Remo en máquina a un brazo', 'remo_maquina', 'traccion_horizontal', 'traccion_superior_horizontal', '{espalda,biceps}', '{hombro,codo}', '{}', 10, 'Pecho apoyado y un brazo cada vez. Lleva el codo atrás sin girar el tronco y vuelve estirando del todo.', null),
  ('dominadas', 'Dominadas', 'barra_dominadas', 'traccion_vertical', 'traccion_superior_vertical', '{espalda,biceps}', '{hombro,codo,muneca}', '{}', 0, 'Agarre algo más ancho que los hombros, palmas hacia delante. Sube hasta pasar la barbilla sin balanceo y baja del todo. El peso es el lastre extra.', null),
  ('dominadas_supinas', 'Dominadas supinas', 'barra_dominadas', 'traccion_vertical', 'traccion_superior_vertical', '{espalda,biceps}', '{hombro,codo,muneca}', '{}', 0, 'Palmas hacia ti, a la anchura de los hombros. Sube sacando el pecho y baja controlando hasta estirar los brazos. El peso es el lastre extra.', null),
  ('jalon_supino', 'Jalón con agarre supino', 'jalon', 'traccion_vertical', 'traccion_superior_vertical', '{espalda,biceps}', '{hombro,codo}', '{}', 25, 'Palmas hacia ti a la anchura de los hombros. Baja la barra al pecho con los codos pegados y sube despacio.', null),
  ('jalon_unilateral_polea', 'Jalón a una mano en polea', 'polea_doble', 'traccion_vertical', 'traccion_superior_vertical', '{espalda,biceps}', '{hombro,codo}', '{}', 5, 'Polea alta y arrodillado o sentado. Baja el asa hacia el hombro llevando el codo a la cadera y sube estirando del todo.', null),
  ('pullover_mancuerna', 'Pullover con mancuerna', 'mancuernas', 'pullover', 'traccion_superior_vertical', '{espalda,pecho}', '{hombro,codo}', '{}', 6, 'Espalda alta apoyada en el banco y brazos casi rectos. Lleva la mancuerna atrás solo hasta un estiramiento cómodo y vuelve sobre el pecho.', null),
  ('sentadilla_barra', 'Sentadilla con barra', 'barra', 'sentadilla', 'empuje_inferior', '{cuadriceps,gluteos}', '{rodilla,cadera,espalda_baja,hombro,cuello_espalda_alta}', '{}', 20, 'Barra sobre la parte alta de la espalda, en el rack con los seguros puestos. Baja con el pecho alto y las rodillas en la línea de los pies.', null),
  ('sentadilla_goblet_manc', 'Sentadilla goblet con mancuerna', 'mancuernas', 'sentadilla', 'empuje_inferior', '{cuadriceps,gluteos}', '{rodilla,cadera}', '{espalda_baja,codo,muneca}', 8, 'Sujeta la mancuerna en vertical pegada al pecho. Baja entre las piernas con el pecho alto y sube empujando con todo el pie.', 'Hay zonas que trabajan poco aquí: carga ligera, recorrido cómodo y sin prisa. Si notas dolor, para y márcalo como molestia.'),
  ('sentadilla_cajon_alto', 'Sentadilla a banco alto con mancuerna', 'mancuernas', 'sentadilla', 'empuje_inferior', '{cuadriceps,gluteos}', '{cadera}', '{rodilla,espalda_baja}', 6, 'Ponte delante de un banco alto con la mancuerna pegada al pecho. Lleva la cadera atrás, toca el banco sin dejarte caer y sube.', 'La rodilla trabaja algo: baja despacio, sin rebotar, y quédate en un recorrido cómodo. Si notas dolor, para y márcalo como molestia.'),
  ('zancada_atras_manc', 'Zancada hacia atrás con mancuernas', 'mancuernas', 'zancada', 'empuje_inferior', '{cuadriceps,gluteos}', '{rodilla,cadera,tobillo}', '{muneca}', 4, 'Da un paso atrás y baja hasta que la rodilla de atrás casi toque el suelo. Vuelve empujando con el pie de delante.', 'Las muñecas aguantan algo de carga: mantenlas rectas, alineadas con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  ('sentadilla_bulgara', 'Sentadilla búlgara con mancuernas', 'mancuernas', 'zancada', 'empuje_inferior', '{cuadriceps,gluteos}', '{rodilla,cadera,tobillo}', '{muneca}', 4, 'Empeine de atrás sobre un banco y pie de delante lejos. Baja recto y sube empujando con el talón de delante.', 'Las muñecas aguantan algo de carga: mantenlas rectas, alineadas con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  ('subida_banco', 'Subida al banco con mancuernas', 'mancuernas', 'zancada', 'empuje_inferior', '{cuadriceps,gluteos}', '{rodilla,cadera,tobillo}', '{muneca}', 4, 'Apoya todo el pie en el banco y sube empujando con esa pierna, sin impulsarte con la de abajo. Baja despacio.', 'Las muñecas aguantan algo de carga: mantenlas rectas, alineadas con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  ('prensa_unilateral', 'Prensa a una pierna', 'prensa_piernas', 'sentadilla', 'empuje_inferior', '{cuadriceps,gluteos}', '{rodilla,cadera}', '{espalda_baja}', 20, 'Un pie en el centro de la plataforma. Baja hasta donde la zona lumbar no se despegue y empuja sin bloquear la rodilla.', 'La zona lumbar trabaja algo: mantén la espalda neutra y no arquees al final. Si notas dolor, para y márcalo como molestia.'),
  ('extension_cuadriceps_unilateral', 'Extensión de cuádriceps a una pierna', 'extension_cuadriceps', 'extension_rodilla', 'empuje_inferior', '{cuadriceps}', '{rodilla}', '{}', 10, 'Rodilla alineada con el eje de la máquina. Sube con una pierna sin impulso, aguanta un segundo arriba y baja despacio.', null),
  ('zancada_multipower', 'Zancada en multipower', 'multipower', 'zancada', 'empuje_inferior', '{cuadriceps,gluteos}', '{rodilla,cadera,tobillo,espalda_baja,hombro,cuello_espalda_alta}', '{}', 10, 'Barra sobre la espalda alta y un pie adelantado. Baja en vertical hasta casi tocar el suelo con la rodilla de atrás y sube.', null),
  ('gemelo_prensa', 'Gemelo en prensa', 'prensa_piernas', 'gemelo', 'empuje_inferior', '{gemelos}', '{tobillo}', '{rodilla}', 20, 'Puntas de los pies en el borde bajo de la plataforma y rodillas casi rectas. Empuja con las puntas y baja hasta notar el estiramiento.', 'La rodilla queda casi quieta, sin bloquearla del todo. Si notas dolor, para y márcalo como molestia.'),
  ('gemelo_sentado_maquina', 'Gemelo sentado en máquina', 'maquina_gemelos_sentado', 'gemelo', 'empuje_inferior', '{gemelos}', '{tobillo}', '{rodilla}', 15, 'Almohadilla sobre los muslos, cerca de las rodillas. Sube los talones todo lo que puedas y baja despacio hasta el estiramiento.', 'La rodilla queda casi quieta, sin bloquearla del todo. Si notas dolor, para y márcalo como molestia.'),
  ('gemelo_multipower', 'Gemelo de pie en multipower', 'multipower', 'gemelo', 'empuje_inferior', '{gemelos}', '{tobillo,espalda_baja,cuello_espalda_alta,hombro}', '{}', 20, 'Barra sobre la espalda alta y puntas en un disco o escalón. Sube todo lo que puedas y baja sin rebotar.', null),
  ('gemelo_mancuerna', 'Gemelo a una pierna con mancuerna', 'mancuernas', 'gemelo', 'empuje_inferior', '{gemelos}', '{tobillo}', '{}', 8, 'Punta del pie en un escalón y una mano apoyada en la pared. Sube todo lo que puedas y baja despacio.', null),
  ('peso_muerto_barra', 'Peso muerto con barra', 'barra', 'bisagra', 'traccion_inferior', '{gluteos,isquiotibiales,espalda}', '{espalda_baja,cadera,rodilla}', '{muneca,cuello_espalda_alta}', 30, 'Barra sobre la mitad del pie y espalda recta. Empuja el suelo con las piernas, con la barra pegada al cuerpo, y baja con el mismo control.', 'Hay zonas que trabajan poco aquí: carga ligera, recorrido cómodo y sin prisa. Si notas dolor, para y márcalo como molestia.'),
  ('peso_muerto_rumano_multipower', 'Peso muerto rumano en multipower', 'multipower', 'bisagra', 'traccion_inferior', '{isquiotibiales,gluteos}', '{espalda_baja,cadera}', '{muneca}', 10, 'Rodillas un poco flexionadas y espalda recta. Lleva la cadera atrás con la barra pegada a las piernas y sube apretando glúteos.', 'Las muñecas aguantan algo de carga: mantenlas rectas, alineadas con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  ('hiperextensiones', 'Hiperextensiones', 'banco_hiperextensiones', 'bisagra', 'traccion_inferior', '{isquiotibiales,gluteos}', '{espalda_baja,cadera}', '{}', 0, 'Almohadilla bajo la cadera. Baja con la espalda recta y sube hasta alinear el cuerpo, sin pasarte arqueando. El peso es el lastre extra.', null),
  ('puente_gluteo_mancuerna', 'Puente de glúteo con mancuerna', 'mancuernas', 'puente_cadera', 'traccion_inferior', '{gluteos,isquiotibiales}', '{cadera}', '{espalda_baja}', 8, 'Tumbado boca arriba con la mancuerna sobre la cadera. Sube apretando los glúteos hasta alinear muslos y tronco, sin arquear.', 'La zona lumbar trabaja algo: mantén la espalda neutra y no arquees al final. Si notas dolor, para y márcalo como molestia.'),
  ('hip_thrust_multipower', 'Hip thrust en multipower', 'multipower', 'puente_cadera', 'traccion_inferior', '{gluteos,isquiotibiales}', '{cadera}', '{espalda_baja}', 20, 'Espalda alta en el banco y barra con protector sobre la cadera. Sube hasta alinear tronco y muslos y baja controlando.', 'La zona lumbar trabaja algo: mantén la espalda neutra y no arquees al final. Si notas dolor, para y márcalo como molestia.'),
  ('patada_gluteo_polea', 'Patada de glúteo en polea', 'polea_doble', 'extension_cadera', 'traccion_inferior', '{gluteos,isquiotibiales}', '{cadera,espalda_baja}', '{}', 5, 'Tobillera en la polea baja y manos apoyadas. Lleva la pierna atrás apretando el glúteo, sin arquear la zona lumbar.', null),
  ('abductores_polea', 'Abducción de cadera en polea', 'polea_doble', 'abduccion_cadera', 'traccion_inferior', '{gluteos}', '{cadera}', '{}', 2.5, 'Tobillera en la polea baja y de lado a la máquina. Separa la pierna sin inclinar el tronco y vuelve despacio.', null),
  ('aductores_maquina', 'Aductores en máquina', 'maquina_aductores', 'aduccion_cadera', 'traccion_inferior', '{aductores}', '{cadera}', '{}', 15, 'Abre la máquina solo hasta un estiramiento cómodo. Junta las piernas sin impulso y vuelve despacio.', null),
  ('peso_muerto_rumano_unilateral', 'Peso muerto rumano a una pierna', 'mancuernas', 'bisagra', 'traccion_inferior', '{isquiotibiales,gluteos}', '{espalda_baja,cadera,tobillo,rodilla}', '{}', 6, 'Apóyate en una pierna con la rodilla un poco flexionada. Inclina el tronco llevando la otra pierna atrás, con la espalda recta, y vuelve.', null),
  ('hip_thrust_mancuerna', 'Hip thrust con mancuerna', 'mancuernas', 'puente_cadera', 'traccion_inferior', '{gluteos,isquiotibiales}', '{cadera}', '{espalda_baja}', 10, 'Espalda alta en el banco y la mancuerna sobre la cadera. Sube hasta alinear tronco y muslos con la barbilla recogida.', 'La zona lumbar trabaja algo: mantén la espalda neutra y no arquees al final. Si notas dolor, para y márcalo como molestia.'),
  ('peso_muerto_rumano_kb', 'Peso muerto rumano con kettlebell', 'kettlebells', 'bisagra', 'traccion_inferior', '{isquiotibiales,gluteos}', '{espalda_baja,cadera}', '{muneca}', 12, 'Pesa con las dos manos delante de los muslos. Lleva la cadera atrás con la espalda recta hasta notar el estiramiento y sube.', 'Las muñecas aguantan algo de carga: mantenlas rectas, alineadas con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  ('patada_gluteo_maquina', 'Patada de glúteo en máquina', 'maquina_gluteo', 'extension_cadera', 'traccion_inferior', '{gluteos,isquiotibiales}', '{cadera,espalda_baja}', '{}', 10, 'Apoya bien el tronco en la máquina. Empuja hacia atrás con el talón apretando el glúteo, sin arquear la zona lumbar.', null),
  ('curl_biceps_maquina', 'Curl de bíceps en máquina', 'maquina_curl', 'flexion_codo', 'brazo', '{biceps}', '{codo,muneca}', '{hombro}', 10, 'Brazos bien apoyados en el pupitre y codos alineados con el eje. Sube sin despegar los brazos y baja despacio sin bloquear.', 'Tu hombro participa poco aquí: brazo apoyado y recorrido cómodo. Si notas dolor, para y márcalo como molestia.'),
  ('curl_scott', 'Curl en banco Scott', 'banco_scott', 'flexion_codo', 'brazo', '{biceps}', '{codo,muneca}', '{hombro}', 5, 'Con barra Z o una mancuerna, la parte de atrás del brazo pegada al pupitre. Sube sin despegarlo y baja sin estirar del todo de golpe.', 'Tu hombro participa poco aquí: brazo apoyado y recorrido cómodo. Si notas dolor, para y márcalo como molestia.'),
  ('curl_biceps_mancuernas', 'Curl de bíceps con mancuernas', 'mancuernas', 'flexion_codo', 'brazo', '{biceps}', '{codo,muneca,hombro}', '{}', 5, 'Codos pegados al cuerpo y tronco quieto. Sube girando las palmas hacia arriba y baja despacio, sin balanceo.', null),
  ('curl_martillo', 'Curl martillo con mancuernas', 'mancuernas', 'flexion_codo', 'brazo', '{biceps,antebrazo}', '{codo,muneca,hombro}', '{}', 5, 'Palmas mirándose durante todo el recorrido y codos pegados. Sube sin mover los hombros y baja controlando.', null),
  ('curl_inclinado_mancuernas', 'Curl en banco inclinado con mancuernas', 'mancuernas', 'flexion_codo', 'brazo', '{biceps}', '{codo,muneca,hombro}', '{}', 4, 'Espalda apoyada en un banco inclinado y brazos colgando. Sube sin adelantar los codos y baja del todo.', null),
  ('curl_biceps_polea', 'Curl de bíceps en polea', 'polea_doble', 'flexion_codo', 'brazo', '{biceps}', '{codo,muneca,hombro}', '{}', 5, 'Polea baja, codos pegados y tronco quieto. Sube la barra o las asas y baja sin dejar que la polea tire de ti.', null),
  ('curl_barra', 'Curl de bíceps con barra', 'barra', 'flexion_codo', 'brazo', '{biceps}', '{codo,muneca,hombro}', '{}', 20, 'Agarre a la anchura de los hombros y codos pegados. Sube sin balancear la espalda y baja despacio.', null),
  ('curl_barra_z', 'Curl con barra Z', 'barra_z', 'flexion_codo', 'brazo', '{biceps}', '{codo,muneca,hombro}', '{}', 10, 'Agarra la barra por la parte inclinada, más cómoda para las muñecas. Codos pegados, sube sin balanceo y baja controlando.', null),
  ('curl_concentrado', 'Curl concentrado con mancuerna', 'mancuernas', 'flexion_codo', 'brazo', '{biceps}', '{codo,muneca,hombro}', '{}', 5, 'Sentado, apoya el codo en la cara interna del muslo. Sube la mancuerna hacia el hombro y baja despacio.', null),
  ('curl_inverso_barra_z', 'Curl inverso con barra Z', 'barra_z', 'flexion_codo', 'brazo', '{biceps,antebrazo}', '{codo,muneca,hombro}', '{}', 7, 'Palmas hacia abajo y muñecas rectas. Sube con los codos pegados y baja despacio.', null),
  ('curl_muneca', 'Curl de muñeca con mancuerna', 'mancuernas', 'flexion_muneca', 'brazo', '{antebrazo}', '{muneca}', '{codo}', 4, 'Antebrazo apoyado en el muslo o el banco y la mano por fuera. Sube solo con la muñeca, en un recorrido cómodo.', 'El codo trabaja poco aquí: no bloquees del todo y sube despacio. Si notas dolor, para y márcalo como molestia.'),
  ('extension_triceps_maquina', 'Extensión de tríceps en máquina', 'maquina_triceps', 'extension_codo', 'brazo', '{triceps}', '{codo,muneca}', '{hombro}', 10, 'Brazos apoyados en el pupitre y codos alineados con el eje. Estira sin bloquear de golpe y vuelve despacio.', 'Tu hombro participa poco aquí: brazo apoyado y recorrido cómodo. Si notas dolor, para y márcalo como molestia.'),
  ('extension_triceps_polea', 'Extensión de tríceps en polea', 'polea_doble', 'extension_codo', 'brazo', '{triceps}', '{codo,muneca,hombro}', '{}', 5, 'Polea alta y codos pegados al cuerpo, sin que se adelanten. Estira los brazos hacia abajo y sube controlando.', null),
  ('extension_triceps_cuerda', 'Extensión de tríceps con cuerda', 'polea_doble', 'extension_codo', 'brazo', '{triceps}', '{codo,muneca,hombro}', '{}', 5, 'Cuerda en la polea alta y codos fijos a los lados. Estira separando los extremos de la cuerda abajo y vuelve despacio.', null),
  ('extension_triceps_cabeza_polea', 'Extensión de tríceps sobre la cabeza en polea', 'polea_doble', 'extension_codo', 'brazo', '{triceps}', '{codo,muneca,hombro}', '{}', 5, 'De espaldas a la polea, con los codos junto a la cabeza. Estira hacia delante y arriba sin abrir los codos.', null),
  ('press_frances_barra_z', 'Press francés con barra Z', 'barra_z', 'extension_codo', 'brazo', '{triceps}', '{codo,muneca,hombro}', '{}', 7, 'Tumbado, brazos verticales. Baja la barra hacia la frente doblando solo los codos y estira sin abrirlos.', null),
  ('extension_triceps_mancuerna_cabeza', 'Extensión de tríceps con mancuerna sobre la cabeza', 'mancuernas', 'extension_codo', 'brazo', '{triceps}', '{codo,muneca,hombro}', '{}', 6, 'Sentado con la espalda apoyada y la mancuerna con las dos manos. Bájala detrás de la cabeza y estira sin abrir los codos.', null),
  ('patada_triceps_mancuerna', 'Patada de tríceps con mancuerna', 'mancuernas', 'extension_codo', 'brazo', '{triceps}', '{codo,muneca,hombro}', '{}', 3, 'Apoya una mano en el banco y pega el codo al cuerpo. Estira el brazo hacia atrás y vuelve sin mover el codo.', null),
  ('press_banca_cerrado', 'Press de banca con agarre cerrado', 'barra', 'empuje_horizontal', 'brazo', '{triceps,pecho}', '{hombro,codo,muneca}', '{}', 20, 'Manos a la anchura de los hombros y codos pegados. Baja la barra a la parte baja del pecho y empuja.', null),
  ('fondos_maquina', 'Fondos en máquina', 'maquina_fondos', 'fondos', 'brazo', '{triceps,pecho}', '{hombro,codo}', '{muneca}', 15, 'Sentado con la espalda apoyada y codos hacia atrás. Empuja hacia abajo hasta estirar y sube sin que los hombros se adelanten.', 'Las muñecas aguantan algo de carga: mantenlas rectas, alineadas con el antebrazo. Si notas dolor, para y márcalo como molestia.'),
  ('crunch_maquina', 'Crunch en máquina', 'maquina_abdominales', 'flexion_tronco', 'core', '{abdominales}', '{espalda_baja}', '{cuello_espalda_alta,hombro}', 15, 'Pecho contra la almohadilla o manos en las asas. Enrolla el tronco llevando las costillas hacia la cadera y vuelve despacio.', 'Hay zonas que trabajan poco aquí: carga ligera, recorrido cómodo y sin prisa. Si notas dolor, para y márcalo como molestia.'),
  ('crunch_polea', 'Crunch en polea', 'polea_doble', 'flexion_tronco', 'core', '{abdominales}', '{espalda_baja,cuello_espalda_alta}', '{hombro}', 10, 'De rodillas frente a la polea alta, cuerda junto a la cabeza. Enrolla el tronco hacia el suelo sin tirar con los brazos.', 'Hay zonas que trabajan poco aquí: carga ligera, recorrido cómodo y sin prisa. Si notas dolor, para y márcalo como molestia.'),
  ('pallof_polea', 'Press Pallof en polea', 'polea_doble', 'antirrotacion', 'core', '{abdominales}', '{hombro,espalda_baja}', '{}', 5, 'De lado a la polea, con el asa en el pecho. Estira los brazos delante sin dejar que el tronco gire y vuelve.', null),
  ('lenador_polea', 'Leñador en polea', 'polea_doble', 'rotacion', 'core', '{abdominales}', '{espalda_baja,hombro}', '{}', 5, 'De lado a la polea, brazos estirados. Lleva el asa en diagonal girando desde la cadera y con los pies firmes.', null),
  ('elevacion_rodillas_paralelas', 'Elevación de rodillas en paralelas', 'paralelas', 'flexion_cadera', 'core', '{abdominales}', '{hombro,cadera,espalda_baja}', '{codo}', 0, 'Antebrazos o manos en las paralelas y hombros lejos de las orejas. Sube las rodillas al pecho sin balanceo. El peso es el lastre extra.', 'El codo trabaja poco aquí: no bloquees del todo y sube despacio. Si notas dolor, para y márcalo como molestia.'),
  ('elevacion_rodillas_colgado', 'Elevación de rodillas colgado', 'barra_dominadas', 'flexion_cadera', 'core', '{abdominales}', '{hombro,cadera,espalda_baja,muneca}', '{}', 0, 'Colgado de la barra sin balancearte. Sube las rodillas hacia el pecho enrollando la pelvis y baja despacio. El peso es el lastre extra.', null),
  ('dead_bug', 'Bicho muerto (dead bug)', 'esterilla', 'antiextension', 'core', '{abdominales}', '{}', '{espalda_baja,cadera}', 0, 'Boca arriba, brazos al techo y rodillas a 90 grados. Estira un brazo y la pierna contraria sin despegar la zona lumbar del suelo. Empieza sin lastre.', 'La zona lumbar trabaja algo: mantén la espalda neutra y no arquees al final. Si notas dolor, para y márcalo como molestia.'),
  ('bird_dog', 'Bird dog (cuadrupedia)', 'esterilla', 'antiextension', 'core', '{abdominales}', '{muneca,hombro}', '{espalda_baja,cadera,rodilla}', 0, 'A cuatro apoyos, espalda neutra. Estira un brazo y la pierna contraria sin girar la cadera, aguanta un segundo y cambia. Empieza sin lastre.', 'Hay zonas que trabajan poco aquí: carga ligera, recorrido cómodo y sin prisa. Si notas dolor, para y márcalo como molestia.'),
  ('crunch_suelo', 'Crunch en el suelo', 'esterilla', 'flexion_tronco', 'core', '{abdominales}', '{espalda_baja,cuello_espalda_alta}', '{}', 0, 'Boca arriba con las rodillas dobladas. Despega solo los hombros del suelo sin tirar del cuello y baja despacio. El peso es el lastre extra.', null),
  ('elevacion_piernas_suelo', 'Elevación de piernas tumbado', 'esterilla', 'flexion_cadera', 'core', '{abdominales}', '{cadera,espalda_baja}', '{}', 0, 'Boca arriba, manos bajo la cadera. Sube las piernas hasta la vertical y bájalas sin que la zona lumbar se despegue.', null),
  ('flexion_lateral_mancuerna', 'Inclinación lateral con mancuerna', 'mancuernas', 'flexion_lateral', 'core', '{abdominales}', '{espalda_baja}', '{hombro}', 10, 'De pie, la mancuerna en una mano junto al muslo. Inclínate hacia ese lado sin girar el tronco y vuelve a la vertical.', 'Hay zonas que trabajan poco aquí: carga ligera, recorrido cómodo y sin prisa. Si notas dolor, para y márcalo como molestia.')
